// Set de calibración (NO incluye las 5 preguntas de la batería ciega)
const casos = [
  { consulta: '¿quién tiene que aprobar un repuesto crítico barato?', esperado: '5.3' },
  { consulta: 'me sobró un pedazo de manguera, ¿lo puedo devolver?',   esperado: '6' },
  { consulta: '¿cada cuánto se cuentan los repuestos clase A?',         esperado: '10' },
  { consulta: '¿qué pasa con un material que no se mueve hace 2 años?', esperado: '11' },
  { consulta: '¿cuál es el precio del rodamiento 6205?',                esperado: 'ninguna' },
  { consulta: '¿cuántos días de vacaciones me corresponden?',           esperado: 'ninguna' },
  { consulta: '¿cuánto cuesta un torquímetro nuevo?',                   esperado: 'ninguna' },
  { consulta: '¿qué EPP necesito para entrar a la sala de calderas?',   esperado: 'ninguna' },
];
return casos.map(c => ({ json: c }));

// Agrupa los resultados por consulta y evalúa umbrales candidatos
const casos = $('Set de calibracion').all().map(i => i.json);
const filas = $input.all();
const TOPK = 3;
const porCaso = casos.map(() => []);
filas.forEach((it, i) => {
  const idx = Math.floor(i / TOPK);
  const sim = 1 - Number(it.json.score);                       // PGVector = distancia coseno
  const secc = it.json.document?.metadata?.seccion ?? '?';
  porCaso[idx].push({ secc, sim: Math.round(sim * 1000) / 1000 });
});

const detalle = casos.map((c, i) => {
  const r = porCaso[i].sort((a, b) => b.sim - a.sim);
  const correcto = r.find(x => x.secc === c.esperado);
  return {
    consulta: c.consulta, esperado: c.esperado,
    top1: r[0] ? `${r[0].secc} · ${r[0].sim}` : '-',
    top2: r[1] ? `${r[1].secc} · ${r[1].sim}` : '-',
    top3: r[2] ? `${r[2].secc} · ${r[2].sim}` : '-',
    sim_respuesta_correcta: correcto ? correcto.sim : null,
    max_sim: r[0] ? r[0].sim : 0
  };
});

const conResp = detalle.filter(d => d.esperado !== 'ninguna');
const sinResp = detalle.filter(d => d.esperado === 'ninguna');
const umbrales = [];
for (let t = 0.62; t <= 0.80001; t += 0.01) {
  const tt = Math.round(t * 100) / 100;
  umbrales.push({
    umbral: tt,
    respuestas_que_pasan: `${conResp.filter(d => (d.sim_respuesta_correcta ?? 0) >= tt).length}/${conResp.length}`,
    ruido_que_pasa: `${sinResp.filter(d => d.max_sim >= tt).length}/${sinResp.length}`
  });
}
return [{ json: {
  min_correcta: Math.min(...conResp.map(d => d.sim_respuesta_correcta ?? 0)),
  max_ruido: Math.max(...sinResp.map(d => d.max_sim)),
  detalle, umbrales
}}];
